def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    lowest_amount = min(v1, v2, v3)

    return {
        "value": lowest_amount,
        "trace": {
            "v1_2018": v1,
            "v2_2017": v2,
            "v3_2016": v3,
            "lowest_amount": lowest_amount,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
